        >>> NLPDataProcessor.get_top_n_words({'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}, 3)
        ['this', 'is', 'test']
        """
        return [word for word, frequency in word_frequency_dictionary[:n]]


