                                                    self.get_update_fields(data),
                                                    condition)

    def get_update_fields(self, data):
        """
        Generates the fields to be updated based on the given data.
        :param data: dict. The data to be updated.
        :return: str. The generated fields.
        >>> sql.get_update_fields({"field1": "value1", "field2": "value2"})
